<article class="stone-card"><a class="stone-image" href="<?= $u('product/' . $product['slug']) ?>"><?php if ($product['images']): ?><img loading="lazy" src="<?= $u($product['images'][0]['path']) ?>" alt="<?= $e($product['images'][0]['alt_text']) ?>"><?php else: ?><span class="material-placeholder">Natural stone<br>Image coming soon</span><?php endif; ?></a><span class="brand-tag"><?= $e($product['brand_name'] ?? $product['category_name']) ?></span><h3><a href="<?= $u('product/' . $product['slug']) ?>"><?= $e($product['name']) ?></a></h3><p class="stone-meta"><?= $e($product['category_name']) ?></p><div class="stone-price"><strong>From <?= $m($product['min_price_minor']) ?></strong></div><p class="note">Choose a variant to see its selling unit.</p><div class="card-bottom"><span><?= $product['in_stock'] ? 'In stock' : 'Currently unavailable' ?></span><a href="<?= $u('product/' . $product['slug']) ?>">Explore ↗</a></div><div class="php-card-actions"><?php foreach (['wishlist'=>'Save ♡','compare'=>'Compare ⇄'] as $route=>$label): ?><form method="post" action="<?= $u($route) ?>"><input type="hidden" name="csrf" value="<?= $e(RequestSecurity::csrfToken()) ?>"><input type="hidden" name="product_id" value="<?= $e($product['id']) ?>"><button class="text-button"><?= $e($label) ?></button></form><?php endforeach; ?></div></article>
